head.script:
scwin.XSL_URL = "/data/exception_transform_WPF-1197_(WSQ-1191)_oz.xsl";

scwin.onpageload = function() {
};

// xsl: 각 요소를 같은 이름으로 다시 만들고 id 속성은 유지, value 속성은 요소 내용으로 출력
scwin.transform = function(xmlStr) {
	var result = WebSquare.xml.transform(xmlStr, location.protocol + "//" + location.host + scwin.XSL_URL);
	if (result && typeof result.then === "function") {
		result.then(function(res) {
			txa_result.setValue(res);
		});
	} else {
		txa_result.setValue(result);
	}
};

scwin.btn_simple_onclick = function(e) {
	scwin.transform("<root>test1</root>");
};

scwin.btn_attr_onclick = function(e) {
	scwin.transform('<root id="r1" value="v1"><item id="a" value="x">skip</item><item value="y"/></root>');
};
